fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    // Determine the length of the input vector.
    let len = a.len();
    // Pre-allocate a vector of i32 with the same capacity as the input length.
    let mut result: Vec<i32> = Vec::with_capacity(len);

    // Loop counter
    let mut idx: usize = 0;
    // Iterate from 0 up to `len`
    while idx < len {
        // Push the value `1` into the result vector.
        result.push(1);
        // Increment the counter.
        idx += 1;
    }

    // At this point, result.len() == len and every element is 1.
    result
}

